begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select has_table('public','store_hours','store_hours exists');
select has_table('public','menus','menus exists');
select has_table('public','menu_sections','menu_sections exists');
select has_table('public','products','products exists');
select has_table('public','menu_items','menu_items exists');
select has_table('public','option_groups','option_groups exists');
select has_table('public','option_values','option_values exists');
select has_table('public','product_option_groups','product_option_groups exists');
insert into public.organizations(id,name,slug) values
('10000000-0000-0000-0000-000000000111','R2 A','r2-a'),('10000000-0000-0000-0000-000000000112','R2 B','r2-b');
insert into public.stores(id,organization_id,public_slug,name,published_at) values
('20000000-0000-0000-0000-000000000111','10000000-0000-0000-0000-000000000111','r2-store-a','Store A',now()),
('20000000-0000-0000-0000-000000000112','10000000-0000-0000-0000-000000000112','r2-store-b','Store B',now()),
('20000000-0000-0000-0000-000000000113','10000000-0000-0000-0000-000000000111','r2-store-c','Store C',null);
insert into public.menus(id,store_id,name) select ('40000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Main' from generate_series(111,113) n;
insert into public.menu_sections(id,store_id,menu_id,name,slug) select ('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('40000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Drinks','drinks' from generate_series(111,113) n;
insert into public.products(id,store_id,name,slug,base_price) select ('60000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Coffee','coffee',30000 from generate_series(111,113) n;
insert into public.menu_items(id,store_id,menu_id,section_id,product_id) select ('70000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('40000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('60000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid from generate_series(111,113) n;
insert into public.option_groups(id,store_id,name,selection_type,required,min_select,max_select) select ('80000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Size','single',true,1,1 from generate_series(111,113) n;
insert into public.option_values(id,store_id,option_group_id,name,is_default) select ('90000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('80000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Small',true from generate_series(111,113) n;
insert into public.product_option_groups(store_id,product_id,option_group_id) select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('60000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('80000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid from generate_series(111,113) n;
insert into public.store_hours(id,store_id,day_of_week,open_time,close_time) select ('b0000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,1,'07:00','22:00' from generate_series(111,113) n;

select throws_ok($$update public.products set base_price=-1$$,'23514',null,'rejects negative product price');
select throws_ok($$update public.option_values set price_adjustment=-1$$,'23514',null,'rejects negative adjustment');
select throws_ok($$update public.products set slug='Not-Kebab'$$,'23514',null,'rejects invalid product slug');
select throws_ok($$update public.menu_sections set slug='Bad Slug'$$,'23514',null,'rejects invalid section slug');
select throws_ok($$update public.store_hours set day_of_week=7$$,'23514',null,'rejects invalid weekday');
select throws_ok($$update public.store_hours set open_time='22:00',close_time='07:00'$$,'23514',null,'rejects overnight interval');
select throws_ok($$update public.store_hours set close_time=open_time$$,'23514',null,'rejects empty interval');
select throws_ok($$update public.store_hours set open_time=null$$,'23514',null,'rejects missing open time');
select throws_ok($$update public.store_hours set is_closed=true$$,'23514',null,'rejects closed day with times');
select throws_ok($$update public.option_groups set min_select=-1$$,'23514',null,'rejects negative minimum');
select throws_ok($$update public.option_groups set max_select=0$$,'23514',null,'rejects maximum below minimum');
select throws_ok($$update public.option_groups set max_select=2$$,'23514',null,'rejects single group maximum');
select throws_ok($$update public.option_groups set required=false$$,'23514',null,'rejects required disagrees with minimum');
select throws_ok($$update public.option_groups set selection_type='unknown'$$,'23514',null,'rejects unknown selection type');
select throws_ok($$insert into public.menu_items(store_id,menu_id,section_id,product_id,sort_order) values ('20000000-0000-0000-0000-000000000111','40000000-0000-0000-0000-000000000111','50000000-0000-0000-0000-000000000111','60000000-0000-0000-0000-000000000112',0)$$,'23503',null,'rejects cross-store menu product');
select throws_ok($$update public.menu_sections set menu_id='40000000-0000-0000-0000-000000000112' where id='50000000-0000-0000-0000-000000000111'$$,'23503',null,'rejects cross-store section menu');
select throws_ok($$update public.menu_items set menu_id='40000000-0000-0000-0000-000000000112' where id='70000000-0000-0000-0000-000000000111'$$,'23503',null,'rejects cross-store placement menu');
select throws_ok($$update public.option_values set option_group_id='80000000-0000-0000-0000-000000000112' where id='90000000-0000-0000-0000-000000000111'$$,'23503',null,'rejects cross-store value group');
select throws_ok($$update public.product_option_groups set product_id='60000000-0000-0000-0000-000000000112' where store_id='20000000-0000-0000-0000-000000000111'$$,'23503',null,'rejects cross-store link product');
select throws_ok($$update public.product_option_groups set option_group_id='80000000-0000-0000-0000-000000000112' where store_id='20000000-0000-0000-0000-000000000111'$$,'23503',null,'rejects cross-store link group');
select throws_ok($$insert into public.option_values(store_id,option_group_id,name,is_default) values ('20000000-0000-0000-0000-000000000111','80000000-0000-0000-0000-000000000111','Other',true)$$,'23505',null,'rejects duplicate active single default');
insert into public.menus(id,store_id,name,sort_order) values ('40000000-0000-0000-0000-000000000114','20000000-0000-0000-0000-000000000111','Second',1);
select throws_ok($$update public.menu_items set menu_id='40000000-0000-0000-0000-000000000114' where id='70000000-0000-0000-0000-000000000111'$$,'23503',null,'section must belong to placement menu even within same store');
insert into public.menus(store_id,name,is_active) values ('20000000-0000-0000-0000-000000000111','Hidden menu',false);
insert into public.products(store_id,name,slug,base_price,is_active) values ('20000000-0000-0000-0000-000000000111','Hidden product','hidden',0,false);
insert into public.option_groups(store_id,name,selection_type,is_active) values ('20000000-0000-0000-0000-000000000111','Hidden group','single',false);
insert into public.option_values(store_id,option_group_id,name,is_active,is_default) values ('20000000-0000-0000-0000-000000000111','80000000-0000-0000-0000-000000000111','Hidden value',false,true);
select is(public.get_storefront_catalog_by_slug('r2-store-a')->'menus',
'[{"id":"40000000-0000-0000-0000-000000000111","name":"Main"},{"id":"40000000-0000-0000-0000-000000000114","name":"Second"}]'::jsonb,'catalog filters inactive menus and orders by sort order');
select is(jsonb_array_length(public.get_storefront_catalog_by_slug('r2-store-a')->'products'),1,'catalog filters inactive products');
select is(jsonb_array_length(public.get_storefront_catalog_by_slug('r2-store-a')->'option_groups'),1,'catalog filters inactive groups');
select is(jsonb_array_length(public.get_storefront_catalog_by_slug('r2-store-a')->'option_groups'->0->'values'),1,'catalog filters inactive option values');
select ok(not (public.get_storefront_catalog_by_slug('r2-store-a')::text ~ 'store_id|is_sold_out|manual_open_state'),'catalog hides tenant UUID and live state');
select is(public.get_storefront_catalog_by_slug('r2-store-c'),null::jsonb,'unpublished store hidden');
select is(public.get_storefront_availability_by_slug('r2-store-c'),null::jsonb,'unpublished availability hidden');
select is(public.get_storefront_catalog_by_slug('missing'),null::jsonb,'missing catalog hidden');
select is(public.get_storefront_availability_by_slug('missing'),null::jsonb,'missing availability hidden');
update public.products set is_sold_out=true where id='60000000-0000-0000-0000-000000000111';
select is(public.get_storefront_availability_by_slug('r2-store-a')->'products','[{"product_id":"60000000-0000-0000-0000-000000000111","is_sold_out":true}]'::jsonb,'availability contains active product sold-out state');
select is(public.get_storefront_availability_by_slug('r2-store-a')->'hours','[{"day_of_week":1,"is_closed":false,"open_time":"07:00:00","close_time":"22:00:00"}]'::jsonb,'availability exposes ordered hours without store UUID');
select throws_ok($$update public.menus set sort_order=-1$$,'23514',null,'menus rejects negative sort');
select throws_ok($$update public.menu_sections set sort_order=-1$$,'23514',null,'menu_sections rejects negative sort');
select throws_ok($$update public.menu_items set sort_order=-1$$,'23514',null,'menu_items rejects negative sort');
select throws_ok($$update public.option_groups set sort_order=-1$$,'23514',null,'option_groups rejects negative sort');
select throws_ok($$update public.option_values set sort_order=-1$$,'23514',null,'option_values rejects negative sort');
select throws_ok($$update public.product_option_groups set sort_order=-1$$,'23514',null,'product_option_groups rejects negative sort');
select throws_ok($$update public.menus set name=''$$,'23514',null,'menus enforces name length');
select throws_ok($$update public.menus set name=repeat('x',121)$$,'23514',null,'menus enforces name length');
select throws_ok($$update public.menu_sections set name=''$$,'23514',null,'menu_sections enforces name length');
select throws_ok($$update public.menu_sections set name=repeat('x',121)$$,'23514',null,'menu_sections enforces name length');
select throws_ok($$update public.products set name=''$$,'23514',null,'products enforces name length');
select throws_ok($$update public.products set name=repeat('x',121)$$,'23514',null,'products enforces name length');
select throws_ok($$update public.option_groups set name=''$$,'23514',null,'option_groups enforces name length');
select throws_ok($$update public.option_groups set name=repeat('x',121)$$,'23514',null,'option_groups enforces name length');
select throws_ok($$update public.option_values set name=''$$,'23514',null,'option_values enforces name length');
select throws_ok($$update public.option_values set name=repeat('x',121)$$,'23514',null,'option_values enforces name length');
select throws_ok($$update public.products set slug=''$$,'23514',null,'products enforces slug length');
select throws_ok($$update public.products set slug=repeat('a',64)$$,'23514',null,'products enforces slug length');
select throws_ok($$update public.menu_sections set slug=''$$,'23514',null,'menu_sections enforces slug length');
select throws_ok($$update public.menu_sections set slug=repeat('a',64)$$,'23514',null,'menu_sections enforces slug length');
select throws_ok($$insert into public.store_hours(store_id,day_of_week,open_time,close_time) values ('20000000-0000-0000-0000-000000000111',1,'08:00','12:00')$$,'23505',null,'one hours row per weekday');
select throws_ok($$insert into public.menu_items(store_id,menu_id,section_id,product_id) select store_id,menu_id,section_id,product_id from public.menu_items limit 1$$,'23505',null,'unique product placement');
select throws_ok($$insert into public.product_option_groups select * from public.product_option_groups limit 1$$,'23505',null,'unique product group link');
select throws_ok($$update public.stores set timezone='Invalid/Zone'$$,'23514',null,'unknown timezone rejected');
select throws_ok($$update public.stores set timezone='asia/ho_chi_minh'$$,'23514',null,'timezone names match exactly');
select lives_ok($$insert into public.store_hours(store_id,day_of_week,is_closed) values ('20000000-0000-0000-0000-000000000111',2,true)$$,'closed day accepts null times');
select is(public.get_storefront_catalog_by_slug('r2-store-a')->'products'->0->>'base_price','30000','money is lossless decimal string');
select is(jsonb_typeof(public.get_storefront_catalog_by_slug('r2-store-a')->'products'->0->'base_price'),'string','price JSON type is string');
update public.products set base_price=9223372036854775807 where id='60000000-0000-0000-0000-000000000111';
select is(public.get_storefront_catalog_by_slug('r2-store-a')->'products'->0->>'base_price','9223372036854775807','bigint maximum is not rounded');

update public.stores set is_active=false where public_slug='r2-store-a';
select is(public.get_storefront_catalog_by_slug('r2-store-a'),null::jsonb,'inactive catalog hidden');
select is(public.get_storefront_availability_by_slug('r2-store-a'),null::jsonb,'inactive availability hidden');
select * from finish();
rollback;
